package com.lifeos.data

import android.content.Context
import android.net.Uri
import com.lifeos.domain.UserSettings
import com.lifeos.domain.balance.*
import com.lifeos.domain.decision.*
import com.lifeos.domain.lifetime.*
import kotlinx.coroutines.flow.first
import org.json.JSONArray
import org.json.JSONObject
import java.math.BigDecimal
import java.time.*

class BackupRepository(private val context:Context,private val settings:SettingsRepository,private val life:LifeRepository){
    suspend fun export(uri:Uri){val s=settings.settings.first();val root=JSONObject().put("format","life-os-backup").put("version",2).put("exportedAt",LocalDateTime.now().toString()).put("settings",JSONObject().apply{
        put("salary",s.monthlySalary.toPlainString());put("workStart",s.workStart);put("lunchStart",s.lunchStart);put("lunchEnd",s.lunchEnd);put("workEnd",s.workEnd);put("lunchEnabled",s.lunchBreakEnabled);put("salaryDay",s.salaryDay);put("birthDate",s.birthDate?.toString());put("retirementType",s.retirementType.name);put("freeTimeEnabled",s.freeTimeEnabled);put("sleepMinutes",s.sleepMinutes);put("commuteMinutes",s.commuteMinutes);put("necessaryLifeEnabled",s.necessaryLifeEnabled);put("necessaryLifeMinutes",s.necessaryLifeMinutes);put("animationsEnabled",s.animationsEnabled);put("funModeEnabled",s.funModeEnabled)
    }).put("balances",JSONArray(life.balances.first().map{JSONObject().apply{put("id",it.id);put("name",it.name);put("price",it.price);put("category",it.category?.name);put("remark",it.remark);put("status",it.status.name);put("pinned",it.isPinned);put("usageMonths",it.expectedUsagePeriodMonths);put("frequencyType",it.usageFrequencyType?.name);put("frequencyValue",it.usageFrequencyValue?.toPlainString());put("oneTimeExtra",it.oneTimeExtraCost);put("monthlyHolding",it.monthlyHoldingCost);put("annualHolding",it.annualHoldingCost);put("createdAt",it.createdAt);put("updatedAt",it.updatedAt);put("purchasedAt",it.purchasedAt?.toString())}})).put("nodes",JSONArray(life.nodes.first().map{JSONObject().apply{put("id",it.id);put("title",it.title);put("type",it.type.name);put("targetAge",it.targetAge);put("targetDate",it.targetDate?.toString());put("createdAt",it.createdAt)}})).put("decisions",JSONArray(life.decisions.first().map{JSONObject().apply{put("id",it.id);put("title",it.title);put("category",it.category?.name);put("background",it.background);put("initialPreference",it.initialPreference.name);put("customPreference",it.customPreference);put("confidence",it.confidence);put("mainReason",it.mainReason);put("biggestRisk",it.biggestRisk);put("expectedResult",it.expectedResult);put("status",it.status.name);put("finalDecision",it.finalDecision);put("createdAt",it.createdAt);put("decidedAt",it.decidedAt?.toString());put("reviewDate",it.reviewDate?.toString())}})).put("reviews",JSONArray(life.reviews.first().map{JSONObject().apply{put("id",it.id);put("decisionId",it.decisionId);put("rating",it.resultRating.name);put("again",it.wouldChooseAgain.name);put("score",it.satisfactionScore);put("correct",it.correctJudgment);put("wrong",it.wrongJudgment);put("reflection",it.reflection);put("reviewedAt",it.reviewedAt)}}))
        context.contentResolver.openOutputStream(uri,"wt")!!.bufferedWriter().use{it.write(root.toString(2))}}
    suspend fun import(uri:Uri){val root=JSONObject(context.contentResolver.openInputStream(uri)!!.bufferedReader().use{it.readText()});require(root.optString("format")=="life-os-backup"&&root.optInt("version")==2){"请选择 Life OS V2 备份文件"};val j=root.getJSONObject("settings");val old=settings.settings.first();settings.save(old.copy(monthlySalary=BigDecimal(j.getString("salary")),workStart=LocalTime.parse(j.getString("workStart")),lunchStart=LocalTime.parse(j.getString("lunchStart")),lunchEnd=LocalTime.parse(j.getString("lunchEnd")),workEnd=LocalTime.parse(j.getString("workEnd")),lunchBreakEnabled=j.getBoolean("lunchEnabled"),salaryDay=j.getInt("salaryDay"),birthDate=j.optString("birthDate").takeIf{it.isNotBlank()&&it!="null"}?.let(LocalDate::parse),retirementType=com.lifeos.domain.RetirementType.valueOf(j.getString("retirementType")),freeTimeEnabled=j.getBoolean("freeTimeEnabled"),sleepMinutes=j.getInt("sleepMinutes"),commuteMinutes=j.getInt("commuteMinutes"),necessaryLifeEnabled=j.getBoolean("necessaryLifeEnabled"),necessaryLifeMinutes=j.getInt("necessaryLifeMinutes"),animationsEnabled=j.getBoolean("animationsEnabled"),funModeEnabled=j.getBoolean("funModeEnabled")))
        root.getJSONArray("balances").objects().forEach{x->life.save(BalanceItem(x.getLong("id"),x.getString("name"),BigDecimal(x.getString("price")),category=x.stringOrNull("category")?.let(BalanceCategory::valueOf),remark=x.optString("remark"),status=BalanceStatus.valueOf(x.getString("status")),isPinned=x.optBoolean("pinned"),expectedUsagePeriodMonths=x.intOrNull("usageMonths"),usageFrequencyType=x.stringOrNull("frequencyType")?.let(UsageFrequencyType::valueOf),usageFrequencyValue=x.stringOrNull("frequencyValue")?.let(::BigDecimal),oneTimeExtraCost=BigDecimal(x.optString("oneTimeExtra","0")),monthlyHoldingCost=BigDecimal(x.optString("monthlyHolding","0")),annualHoldingCost=BigDecimal(x.optString("annualHolding","0")),createdAt=LocalDateTime.parse(x.getString("createdAt")),updatedAt=LocalDateTime.parse(x.getString("updatedAt")),purchasedAt=x.stringOrNull("purchasedAt")?.let(LocalDateTime::parse)))}
        root.getJSONArray("nodes").objects().forEach{x->life.save(LifeNode(x.getLong("id"),x.getString("title"),LifeNodeType.valueOf(x.getString("type")),x.intOrNull("targetAge"),x.stringOrNull("targetDate")?.let(LocalDate::parse),LocalDateTime.parse(x.getString("createdAt"))))}
        root.getJSONArray("decisions").objects().forEach{x->life.save(Decision(id=x.getLong("id"),title=x.getString("title"),category=x.stringOrNull("category")?.let(DecisionCategory::valueOf),background=x.optString("background"),initialPreference=x.stringOrNull("initialPreference")?.let(DecisionPreference::valueOf)?:DecisionPreference.UNDECIDED,customPreference=x.optString("customPreference"),confidence=x.intOrNull("confidence"),mainReason=x.optString("mainReason"),biggestRisk=x.optString("biggestRisk"),expectedResult=x.optString("expectedResult"),status=DecisionStatus.valueOf(x.getString("status")),finalDecision=x.optString("finalDecision"),createdAt=LocalDateTime.parse(x.getString("createdAt")),decidedAt=x.stringOrNull("decidedAt")?.let(LocalDateTime::parse),reviewDate=x.stringOrNull("reviewDate")?.let(LocalDate::parse)))}
        root.getJSONArray("reviews").objects().forEach{x->life.save(DecisionReview(x.getLong("id"),x.getLong("decisionId"),ResultRating.valueOf(x.getString("rating")),ChooseAgain.valueOf(x.getString("again")),x.intOrNull("score"),x.optString("correct"),x.optString("wrong"),x.optString("reflection"),LocalDateTime.parse(x.getString("reviewedAt"))))}}
}
private fun JSONArray.objects()=sequence{for(i in 0 until length())yield(getJSONObject(i))}
private fun JSONObject.stringOrNull(key:String)=if(isNull(key))null else optString(key).takeIf{it.isNotBlank()&&it!="null"}
private fun JSONObject.intOrNull(key:String)=if(isNull(key))null else optInt(key)
